import json,re,sys
R="reports/mindmap-pass/2026-10-16-competitor/drafts/"
def load(s): return json.load(open(R+s+".json"))
def walk_replace(d,pairs):
    miss=[]
    def fix(t):
        for a,b in pairs:
            if a in t: t=t.replace(a,b)
        return t
    txt=json.dumps(d,ensure_ascii=False)
    out=txt
    for a,b in pairs:
        ea=json.dumps(a,ensure_ascii=False)[1:-1]; eb=json.dumps(b,ensure_ascii=False)[1:-1]
        if ea not in out: miss.append(a[:70])
        out=out.replace(ea,eb)
    return json.loads(out),miss
def clean(d):
    def c(t):
        t=re.sub(r"[ \t]+\n","\n",t); t=re.sub(r"\n\n[ \t]+","\n\n",t); t=re.sub(r"\n{3,}","\n\n",t)
        return t.strip()
    for k in ["introText","cardBlurb"]: d[k]=c(d[k])
    for s in d["sections"]: s["body"]=c(s["body"])
    for f in d["faqs"]: f["answer"]=c(f["answer"])
    for k in ["subtitle","ctaTitle","ctaText","ctaButton","faqItems"]: d.pop(k,None)
    return d
